before.lib/shipping.ex:
defmodule Shipping do
  @moduledoc "Sandbox carrier model: keys deduplicate atomically for the lifetime of this server. First success may lose its reply."
  def start_link, do: Agent.start_link(fn -> %{} end)
  def create(server, key, order) do
    Agent.get_and_update(server, fn shipments ->
      case Map.fetch(shipments, key) do
        {:ok, ^order} -> {{:ok, key}, shipments}
        {:ok, _other} -> {{:error, :key_conflict}, shipments}
        :error -> {{:error, :timeout}, Map.put(shipments, key, order)}
      end
    end)
  end
  def shipments(server), do: Agent.get(server, & &1)
end

before.lib/ship_order.ex:
defmodule ShipOrder do
  @doc "Submit one shipment for an order using its durable operation_id."
  def run(carrier, order), do: Shipping.create(carrier, order.operation_id, order)
end

